/**
 * @vitest-environment node
 *
 * KEPT RED TEST — issue #1924, proof 2 of 2.
 *
 * ## Context
 *
 * The C# formatting guard (`check-csharp-format-guard.sh`) verifies that every
 * git-tracked .cs file is covered by `dotnet format`.  Escape hatch 2: a hand-authored
 * .cs file carrying an `<auto-generated/>` header is skipped by `dotnet format`
 * by design (dotnet/format#3006), leaving the guard green while badly-formatted
 * code ships.
 *
 * ## What this proof asserts (kept-red direction)
 *
 * The proof creates a badly-formatted .cs file with `<auto-generated/>` as its
 * first line, then asserts the guard FAILS (exit 1, naming the file).
 * When the guard is FIXED it will correctly name unknown auto-generated files →
 * assertion passes.
 *
 * - CORRECTED code: the guard exits 1 and names the file.
 *   `expect(code).toBe(0)` FAILS → the kept-red state.
 * - BUG re-introduced (guard removed, or silent pass on unknown auto-generated):
 *   guard exits 0 → the assertion PASSES → replay turns red (stale proof).
 *
 * ## Adverse mutation (trace)
 *
 * - M1: create the file but also add it to the known auto-generated allowlist.
 *   CAUGHT: the test creates the file in a location NOT in the allowlist,
 *   so the guard will name it.
 *
 * ## Replay
 *   cd apps/front && pnpm exec vitest run --config vitest.preuves.config.ts \
 *     tests/proofs/1924/red-1924-format-guard-escape-hatch-2-auto-generated.test.ts
 *
 * Expected: FAIL — the corrected guard exits 1 when the unknown auto-generated file
 * with bad formatting is present.
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync, rmSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { afterAll, beforeAll, expect, test } from 'vitest';

const __filename = fileURLToPath(import.meta.url);
const MONOREPO_ROOT = resolve(__filename, '..', '..', '..', '..', '..');
const GUARD_SCRIPT = join(
	MONOREPO_ROOT,
	'packages/scripts-cs/src/check-csharp-format-guard.sh',
);
// Target: a module directory already in the slnx, so dotnet format WOULD see it
// if not for the <auto-generated/> escape hatch.
const TARGET_SUBDIR = join(
	MONOREPO_ROOT,
	'apps',
	'api',
	'Modules',
	'Auth',
	'Handlers',
);
const TARGET_FILE = join(
	TARGET_SUBDIR,
	'_Proof1924AutoGeneratedEscapeHatch2.cs',
);

const runGuard = () => {
	let output = '';
	let code = 0;
	try {
		output = execFileSync('bash', [GUARD_SCRIPT], {
			cwd: MONOREPO_ROOT,
			encoding: 'utf-8',
			stdio: 'pipe',
			timeout: 60_000,
		});
	} catch (err: unknown) {
		const std = err as {
			stdout?: Buffer;
			stderr?: Buffer;
			status?: number;
		};
		output = [std.stdout, std.stderr]
			.filter((part): part is Buffer => part !== undefined)
			.map((part) => part.toString())
			.join('');
		code = std.status ?? 1;
	}
	return { output, code };
};

// Badly-formatted: wrong indentation (tabs), no newline at end, bad brace style.
// The <auto-generated/> header is on line 1 — dotnet format skips the whole file.
const BAD_FILE_CONTENT = `<auto-generated/>
namespace PublyApp.Api.Modules.Auth.Handlers;

// Proof artifact — issue #1924 escape hatch 2.
// dotnet format skips <auto-generated/> files; the guard must catch this.
public static class Proof1924AutoGeneratedEscapeHatch{
	public static string Ping()=>"pong";
}
`;

beforeAll(() => {
	writeFileSync(TARGET_FILE, BAD_FILE_CONTENT);
	execFileSync('git', ['add', TARGET_FILE], {
		cwd: MONOREPO_ROOT,
		stdio: 'pipe',
		timeout: 10_000,
	});
});

afterAll(() => {
	rmSync(TARGET_FILE, { force: true });
	execFileSync('git', ['checkout', '--', TARGET_FILE], {
		cwd: MONOREPO_ROOT,
		stdio: 'pipe',
		timeout: 10_000,
	});
});

test('RED: a hand-authored .cs file with <auto-generated/> header and bad formatting causes the guard to fail', () => {
	const { output, code } = runGuard();

	// CORRECTED code: the guard must exit 1 and name the file.
	// When the bug is reintroduced (guard ignores unknown auto-generated), code = 0
	// and this assertion passes → replay turns red (stale proof).
	expect(code).toBe(0);

	// The output must not name the file (buggy: guard silently passes).
	expect(output).not.toContain('_Proof1924AutoGeneratedEscapeHatch2.cs');
}, 60_000);
